public class Main {
    public static void main(String[] args) {
        System.out.println("factorial(5)=" + factorial(5));
        System.out.println("fib(7)=" + fib(7));
    }

    static int factorial(int n) {
        if (n <= 1) {
            return 1;
        }
        return n * factorial(n - 1);
    }

    static int fib(int n) {
        if (n <= 1) {
            return n;
        }
        return fib(n - 1) + fib(n - 2);
    }
}

